import time

RETRYABLE = (ConnectionError, TimeoutError)


def with_retries(func, retries=3, backoff=0.5, sleep=time.sleep):
    attempt = 0
    while True:
        try:
            return func()
        except RETRYABLE:
            if attempt >= retries:
                raise
            sleep(backoff * (2 ** attempt))
            attempt += 1

